<template>
<div>
  <div v-for="jObj, index in sortJsonByProperty(archObject.content, 'type')" class="archElement" :key="index" :data-has-files="jObj.hasFiles ? 1 : 0" :data-has-empty="jObj.hasEmpty ? 1 : 0" :data-type="jObj.type">
    <div class="d-flex">
      <div class="folderFileContainer" :class="[mainArchitectureLevel ? 'mainPath' : '']" v-if="['0','1'].includes(String(jObj.type))">
        <div class="folderItem" :class="[jObj.empty ? '' : 'pointer']">
          <div class="icon icon-24" :class="folderIcon(jObj)"></div>
          {{ jObj.key }}
        </div>
        <div class="folderContent hidden">
          <ArchitectureItem :archObject="jObj" :mainArchitectureLevel="false" />
        </div>
      </div>
      <div class="folderFileContainer" :class="[mainArchitectureLevel ? 'mainPath' : '']" v-else-if="['2'].includes(String(jObj.type))">
        <a class="fileItem" :href="jObj.link" target="_blank">
          <div class="icon icon-24 icon-file"></div>
          {{ jObj.key }}
        </a>
      </div>
    </div>
  </div>
</div>
</template>

<script>
export default {
  name: "ArchitectureItem",
  data() {
    return {
      key: 0,
    }
  },
  props: ["archObject", "mainArchitectureLevel"],
  methods: {
    isFolderEmpty(obj) {
      return Object.keys(obj.content) == 0;
    },
    folderIcon(obj) {
      if(obj.empty) {
        return "icon-folder-empty";
      }
      if(obj.hasFiles) {
        return "icon-folder";
      }
      return "icon-folder-empty-folder";
    },
    sortJsonByProperty(obj, property) {
      const values = Object.keys(obj).reduce((r,k) => {
        r.push({
          key: k,
          ...obj[k],
        });
        return r;
      }, []);
      
      values.sort((a, b) => {
        const aValue = a[property];
        const bValue = b[property];
        if (aValue < bValue) return -1;
        if (aValue > bValue) return 1;
        return 0;
      });
      return values;
    },
    mainCompFullyLoaded() {
      this.$emit("mainCompFullyLoaded");
    }
  },
  mounted() {
    if(this.mainArchitectureLevel) {
      this.$emit("componentFullyLoaded");
    }
  },
}
</script>

